{"path": "affine_cipher.py", "content": "from math import gcd
from string import ascii_lowercase

M = len(ascii_lowercase)


def _check_key(a):
    if gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _translate(text, func):
    result = []
    for char in text.lower():
        if char in ascii_lowercase:
            result.append(ascii_lowercase[func(ord(char) - ord("a")) % M])
        elif char.isdigit():
            result.append(char)
    return "".join(result)


def encode(plain_text, a, b):
    _check_key(a)
    text = _translate(plain_text, lambda i: a * i + b)
    return " ".join(text[i:i + 5] for i in range(0, len(text), 5))


def decode(ciphered_text, a, b):
    _check_key(a)
    inverse = pow(a, -1, M)
    return _translate(ciphered_text, lambda y: inverse * (y - b))
